<?php $items=products($store); ?><section class="page-hero"><div class="container narrow"><p class="eyebrow">Shop</p><h1>Products</h1><p>Browse the configurable demo catalogue. Replace these products with the store's real catalogue when adapting the project.</p></div></section><section class="section"><div class="container"><div class="product-grid"><?php foreach($items as $product):?><article class="product-card"><p class="eyebrow"><?=e($product['stock'])?> in stock</p><h2><a href="/products/<?=e($product['slug'])?>"><?=e($product['name'])?></a></h2><p><?=e($product['summary'])?></p><p class="price"><?=e(money((int)$product['price_pence'],$store))?></p><div class="actions"><a class="button secondary" href="/products/<?=e($product['slug'])?>">Details</a><form method="post" action="/cart"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="slug" value="<?=e($product['slug'])?>"><button class="button primary" type="submit">Add to basket</button></form></div></article><?php endforeach;?></div></div></section>
